<template>
  <div class="app-root">
    <header class="topbar"><div class="topbar-left"><svg class="logo-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v6c0 1.66 4.03 3 9 3s9-1.34 9-3V5"/><path d="M3 11v6c0 1.66 4.03 3 9 3s9-1.34 9-3v-6"/></svg><span class="brand-name">DB Agent</span><span class="sep"></span><el-select v-model="database" filterable placeholder="选择数据库" @change="onDbChange" :loading="loadingDbList" size="small" class="topbar-db"><el-option v-for="db in databaseList" :key="db.name" :label="db.name" :value="db.name"></el-option></el-select><span class="db-indicator" v-if="dbConfirmed"><span class="db-dot"></span>{{ database }}</span></div><div class="topbar-right"><span class="badge" :class="{ok:backendOnline}">{{ backendOnline?'已连接':'离线' }}</span><span class="sep"></span><button class="tb-btn" @click="$router.push('/settings')" title="设置"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 00.33 1.82l.06.06a2 2 0 010 2.83 2 2 0 01-2.83 0l-.06-.06a1.65 1.65 0 00-1.82-.33 1.65 1.65 0 00-1 1.51V21a2 2 0 01-2 2 2 2 0 01-2-2v-.09A1.65 1.65 0 009 19.4a1.65 1.65 0 00-1.82.33l-.06.06a2 2 0 01-2.83 0 2 2 0 010-2.83l.06-.06A1.65 1.65 0 004.68 15a1.65 1.65 0 00-1.51-1H3a2 2 0 01-2-2 2 2 0 012-2h.09A1.65 1.65 0 004.6 9a1.65 1.65 0 00-.33-1.82l-.06-.06a2 2 0 010-2.83 2 2 0 012.83 0l.06.06A1.65 1.65 0 009 4.68a1.65 1.65 0 001-1.51V3a2 2 0 012-2 2 2 0 012 2v.09a1.65 1.65 0 001 1.51 1.65 1.65 0 001.82-.33l.06-.06a2 2 0 012.83 0 2 2 0 010 2.83l-.06.06A1.65 1.65 0 0019.4 9a1.65 1.65 0 001.51 1H21a2 2 0 012 2 2 2 0 01-2 2h-.09a1.65 1.65 0 00-1.51 1z"/></svg></button><button class="tb-btn" @click="$router.push('/favorites')" title="收藏"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg></button><span class="user-role-tag">{{ auth.state.role==='admin'?'管理员':'只读' }}</span><span class="user-name">{{ auth.state.displayName||auth.state.username }}</span><button class="tb-btn" @click="handleLogout" title="退出"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 21H5a2 2 0 01-2-2V5a2 2 0 012-2h4M16 17l5-5-5-5M21 12H9"/></svg></button></div></header>
    <div class="body-wrap">
      <nav class="activity-bar"><button class="act-btn" :class="{active:navTab==='chat'}" @click="navTab='chat'" title="对话"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2z"/></svg><span class="act-label">对话</span></button><button class="act-btn" :class="{active:navTab==='objects'}" @click="navTab='objects'" title="数据库对象"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M21 12c0 1.66-4 3-9 3s-9-1.34-9-3"/><path d="M3 5v14c0 1.66 4 3 9 3s9-1.34 9-3V5"/></svg><span class="act-label">对象</span></button><button class="act-btn" :class="{active:navTab==='history'}" @click="navTab='history'" title="会话历史"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg><span class="act-label">历史</span></button><div class="act-spacer"></div><button class="act-btn" @click="runInspectChat" title="表巡检"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="3" width="20" height="14" rx="2" ry="2"/><line x1="8" y1="21" x2="16" y2="21"/><line x1="12" y1="17" x2="12" y2="21"/></svg><span class="act-label">巡检</span></button><button class="act-btn" @click="openSqlForDiagnosis" title="诊断"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg><span class="act-label">诊断</span></button><button class="act-btn" @click="showModal('generate')" title="生成数据"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="16 18 22 12 16 6"/><polyline points="8 6 2 12 8 18"/></svg><span class="act-label">生成</span></button><button class="act-btn" @click="toggleSqlEditor" title="SQL编辑器"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="4 17 10 11 4 5"/><line x1="12" y1="19" x2="20" y2="19"/></svg><span class="act-label">SQL</span></button><button class="act-btn" @click="$router.push('/audit')" title="审计日志"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M16 4h2a2 2 0 012 2v14a2 2 0 01-2 2H6a2 2 0 01-2-2V6a2 2 0 012-2h2"/><rect x="8" y="2" width="8" height="4" rx="1" ry="1"/></svg><span class="act-label">审计</span></button><div class="act-spacer"></div><button class="act-btn" v-if="auth.isAdmin" @click="$router.push('/admin/users')" title="管理"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 00-3-3.87M16 3.13a4 4 0 010 7.75"/></svg><span class="act-label">管理</span></button></nav>
      <aside class="side-panel" v-if="navTab!=='chat'"><template v-if="navTab==='objects'"><div class="panel-title">数据库对象</div><div v-if="!dbConfirmed" class="panel-empty">请先选择数据库</div><div v-else-if="loadingObjects" class="panel-empty">加载中...</div><div v-else class="tree-list"><template v-for="obj in dbObjects" :key="obj.name"><div class="tree-row" @click="toggleObject(obj)"><svg class="tree-chevron" :class="{open:obj.expanded}" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="9 18 15 12 9 6"/></svg><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#81c995" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="2"/><line x1="3" y1="9" x2="21" y2="9"/><line x1="9" y1="21" x2="9" y2="9"/></svg><span class="tree-name">{{ obj.name }}</span></div><div v-if="obj.expanded&&obj.columns" class="tree-children"><div v-for="col in obj.columns" :key="col.name" class="tree-col"><span>{{ col.name }}</span><span class="col-t">{{ col.type }}</span></div></div></template></div></template><template v-if="navTab==='history'"><div class="panel-title">会话历史</div><button class="panel-btn" @click="newSession">+ 新建会话</button><div v-if="sessionHistory.length" class="hist-list"><div v-for="s in sessionHistory" :key="s.id" class="hist-row" :class="{on:s.id===sessionId}" @click="loadSession(s.id)" @contextmenu.prevent="onCtx($event,s)">{{ s.preview }}</div></div><div v-else class="panel-empty">暂无会话</div></template></aside>
      <main class="chat-zone"><canvas ref="bgCanvas" class="bg-canvas"></canvas><div class="progress-bar" v-if="isLoading"><div class="progress-bar-fill" :style="{width:toolProgress+'%'}"></div></div><div class="msg-stream" ref="chatHistory"><div class="welcome" v-if="messages.length===0&&!streamingContent"><svg class="welcome-icon" viewBox="0 0 24 24" fill="none" stroke="var(--accent)" stroke-width="1.2"><ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v6c0 1.66 4.03 3 9 3s9-1.34 9-3V5"/><path d="M3 11v6c0 1.66 4.03 3 9 3s9-1.34 9-3v-6"/></svg><h2>数据库 AI 助手</h2><p>用自然语言查询和分析你的 MySQL 数据库</p><div class="wel-cards"><div class="wel-card" v-for="c in quickCards" :key="c.text" @click="quickAction(c.text)"><span class="wel-emoji">{{ c.emoji }}</span><span>{{ c.label }}</span></div></div></div>
        <template v-for="msg in messages" :key="msg.id"><div class="msg-row" :class="msg.role"><div class="msg-avatar" v-if="msg.role==='assistant'"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="var(--accent)" stroke-width="2"><ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v6c0 1.66 4.03 3 9 3s9-1.34 9-3V5"/></svg></div><div class="msg-body">
          <div class="cot-fold" v-if="msg.reasoning">
            <button class="cot-toggle" @click="msg.cotOpen=!msg.cotOpen">{{msg.cotOpen?'收起推理链':'展开推理链'}}</button>
            <div class="cot-content" v-if="msg.cotOpen" v-text="msg.reasoning"></div>
          </div>
          <div class="msg-content" v-html="renderContent(msg.content)"></div>
          <div class="tool-cards" v-if="msg.toolCalls&&msg.toolCalls.length">
            <button class="tool-toggle" @click="msg.toolDrawerOpen=!msg.toolDrawerOpen">{{msg.toolDrawerOpen?'收起':'展开'}} 工具调用 ({{msg.toolCalls.length}}步)</button>
            <div class="tool-list" v-if="msg.toolDrawerOpen">
              <div class="tool-item" v-for="(tc,i) in msg.toolCalls" :key="i" :class="tc.status">
                <span class="tool-dot"></span>
                <span class="tool-name">{{tc.name}}</span>
                <span class="tool-status">{{tc.status==='success'?'✓':tc.status==='error'?'✗':'…'}}</span>
              </div>
            </div>
          </div>
        </div></div></template>
        <div class="msg-row assistant" v-if="streamingContent"><div class="msg-avatar"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="var(--accent)" stroke-width="2"><ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v6c0 1.66 4.03 3 9 3s9-1.34 9-3V5"/></svg></div><div class="msg-body"><div class="cot-fold" v-if="streamingReasoning"><button class="cot-toggle" @click="showReasoning=!showReasoning">{{showReasoning?'收起推理链':'展开推理链'}}</button><div class="cot-content" v-if="showReasoning" v-text="streamingReasoning"></div></div><div class="msg-content" v-html="renderContent(streamingContent)"></div></div></div>
        <div v-if="resultTable.visible" class="card" style="margin-top:8px"><div class="card-header"><span>{{ resultTable.rows.length }}行×{{ resultTable.columns.length }}列</span><div class="flex gap-2"><el-button size="small" text @click="copyResultTable">复制</el-button><el-button size="small" text @click="exportResultCSV">导出CSV</el-button><el-button size="small" text @click="resultTable.visible=false">关闭</el-button></div></div><el-table :data="resultTable.rows" size="small" max-height="300" border style="width:100%"><el-table-column v-for="col in resultTable.columns" :key="col" :prop="col" :label="col" min-width="100" show-overflow-tooltip /></el-table></div></div><div class="input-zone"><div class="input-box"><textarea v-model="userInput" class="chat-input" placeholder="输入问题，Enter发送，Shift+Enter换行..." @keydown="handleKeydown" :disabled="isLoading" rows="1"></textarea><button class="send-btn" @click="sendMessage" :disabled="isLoading||!userInput.trim()"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg></button></div><div v-if="sqlEditorOpen" class="sql-editor-card"><div class="sql-editor-header"><span>SQL 编辑器</span><div class="flex gap-2"><el-button size="small" text @click="formatEditorSql">格式化</el-button><el-button size="small" text @click="doExplainSql" :disabled="!(editorSql||'').trim().toUpperCase().startsWith('SELECT')">🔍 EXPLAIN</el-button><el-button size="small" text @click="sqlEditorOpen=false">关闭</el-button></div></div><textarea v-model="editorSql" class="sql-textarea" rows="4" placeholder="SELECT ..."></textarea><div class="flex gap-2" style="margin-top:6px"><el-button size="small" type="primary" @click="executeEditorSql" :loading="executingSql">▶ 执行</el-button><el-button size="small" @click="doExplainSql" :disabled="!(editorSql||'').trim().toUpperCase().startsWith('SELECT')">🔍 EXPLAIN</el-button></div></div></div></main>
    </div>
    <el-dialog v-model="generateOpen" title="测试数据生成" width="660px"><div class="modal-body"><div class="form-grid"><div class="field-row"><label>数据库</label><el-input v-model="genDb" :placeholder="'默认:'+database" size="small" /></div><div class="field-row"><label>表名</label><el-input v-model="genTable" placeholder="输入表名" size="small" /></div></div><div class="field-row" style="margin-top:10px"><label>业务场景</label><el-input v-model="genScenario" placeholder="描述数据场景" size="small" /></div><div class="field-row" style="margin-top:10px"><label>生成行数</label><el-input-number v-model="genCount" :min="1" :max="500" size="small" class="w-full" /></div><div class="flex gap-2" style="margin-top:12px"><el-button type="primary" @click="runGenerate(false)" :disabled="genLoading" style="flex:1">生成SQL</el-button><el-button @click="runGenerate(true)" :disabled="genLoading||!genHasSql" style="flex:1">生成并执行</el-button></div><div v-if="genResult" style="margin-top:14px"><div v-if="genResult.inserted!==undefined" :class="genResult.inserted>0?'result-ok':'result-err'">{{ genResult.inserted>0?'成功插入'+genResult.inserted+'条':'插入失败' }}</div><pre class="code-block" v-for="(sql,i) in (genResult.insert_statements||[]).slice(0,3)" :key="i"><code>{{ sql }}</code></pre></div></div></el-dialog>
  </div>
</template>
<script setup>
import { ref, nextTick, onMounted, onUnmounted } from 'vue'
import { useRouter } from 'vue-router'
import axios from 'axios'
import hljs from 'highlight.js/lib/core'
import sqlLang from 'highlight.js/lib/languages/sql'
import 'highlight.js/styles/atom-one-dark.css'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useAuth } from '../store/auth.js'
import { API_BASE, STORAGE_KEYS } from '../config.js'
hljs.registerLanguage('sql', sqlLang)
const router = useRouter(); const auth = useAuth()
function authHeaders() { return auth.getAuthHeaders() }
const database = ref(''), databaseList = ref([]), loadingDbList = ref(false), dbConfirmed = ref(false)
const sessionId = ref(''), userInput = ref(''), messages = ref([]), streamingContent = ref(''), streamingReasoning = ref(''), showReasoning = ref(true), isLoading = ref(false), backendOnline = ref(false)
const sessionHistory = ref([]), lastQuerySql = ref(null), toolProgress = ref(0)
const navTab = ref('chat'), generateOpen = ref(false)
const chatHistory = ref(null), sqlEditorOpen = ref(false), editorSql = ref('SELECT '), executingSql = ref(false)
const resultTable = ref({ visible: false, columns: [], rows: [] }), dbObjects = ref([]), loadingObjects = ref(false)
const selectedModel = ref(localStorage.getItem('db_agent_model') || 'deepseek-chat')
const availableModels = [{ value: 'deepseek-chat', label: 'DeepSeek V3' },{ value: 'deepseek-reasoner', label: 'DeepSeek R1' }]
const resultLimit = ref(100)
const genDb = ref(''), genTable = ref(''), genScenario = ref(''), genCount = ref(50), genLoading = ref(false), genResult = ref(null), genHasSql = ref(false)
const quickCards = [{ emoji:'🔎', label:'查看表结构', text:'查看有哪些表' },{ emoji:'💬', label:'数据查询', text:'帮我查一下有哪些数据' },{ emoji:'🩺', label:'表巡检', text:'帮我巡检表结构' }]
function handleLogout(){auth.logout();router.push('/login')}
function showModal(name){if(name==='generate')generateOpen.value=true}
function safeStr(obj){try{return JSON.stringify(obj,null,2)}catch(e){return String(obj)}}
async function loadDatabases(){loadingDbList.value=true;try{const r=await axios.get(`${API_BASE}/databases`,{headers:authHeaders(),timeout:5000});databaseList.value=r.data?r.data.databases||[]:[];if(databaseList.value.length&&!database.value){database.value=(databaseList.value.find(d=>!d.system)||databaseList.value[0]).name;onDbChange()}}catch{databaseList.value=[]};loadingDbList.value=false}
function onDbChange(){if(database.value){dbConfirmed.value=true;axios.post(`${API_BASE}/session/create`,{database:database.value},{headers:authHeaders()}).catch(()=>{});loadDbObjects()}}
async function loadDbObjects(){if(!dbConfirmed.value)return;loadingObjects.value=true;try{const r=await axios.get(`${API_BASE}/objects`,{params:{database:database.value},headers:authHeaders(),timeout:10000});const tables=(r.data&&r.data.tables)||[];const views=(r.data&&r.data.views)||[];dbObjects.value=tables.concat(views).map(o=>({...o,expanded:false,columns:null}))}catch{dbObjects.value=[]}finally{loadingObjects.value=false}}
async function toggleObject(obj){if(obj.columns){obj.expanded=!obj.expanded;return};if(obj.expanded){obj.expanded=false;return};obj.expanded=true;try{const r=await axios.get(`${API_BASE}/objects/${database.value}/${obj.name}/columns`,{headers:authHeaders()});obj.columns=(r.data&&r.data.columns)||[]}catch{obj.columns=[]}}
function loadSessionHistoryFromStorage(){try{const r=localStorage.getItem(STORAGE_KEYS.sessions);if(r)sessionHistory.value=JSON.parse(r)}catch{sessionHistory.value=[]}}
function saveLocalSnapshot(){if(!sessionId.value||!messages.value.length)return;try{localStorage.setItem(STORAGE_KEYS.snapshot(sessionId.value),JSON.stringify(messages.value.slice(-50).map(m=>({id:m.id,role:m.role,content:m.content,toolCalls:m.toolCalls||[]}))))}catch{}}
function saveHistoryToStorage(){try{localStorage.setItem(STORAGE_KEYS.sessions,JSON.stringify(sessionHistory.value.slice(0,20).map(s=>({id:s.id,preview:s.preview}))))}catch{}}
function newSession(){if(sessionId.value&&messages.value.length>0){if(!sessionHistory.value.find(s=>s.id===sessionId.value)){const pu=messages.value.filter(m=>m.role==='user')[0];sessionHistory.value.unshift({id:sessionId.value,preview:pu?(pu.content||'').slice(0,30):'新会话'})}saveLocalSnapshot();saveHistoryToStorage()};sessionId.value='s_'+Date.now();messages.value=[];streamingContent.value='';streamingReasoning.value='';lastQuerySql.value=null;toolProgress.value=0;resultTable.value={visible:false,columns:[],rows:[]}}
function loadSession(id){if(sessionId.value===id)return;if(sessionId.value&&messages.value.length>0){if(!sessionHistory.value.find(s=>s.id===sessionId.value)){const pu=messages.value.find(m=>m.role==='user');sessionHistory.value.unshift({id:sessionId.value,preview:pu?(pu.content||'').slice(0,30):'新会话'})}saveLocalSnapshot();saveHistoryToStorage()};restoreSession(id)}
async function restoreSession(id){try{const k=STORAGE_KEYS.snapshot(id);const r=localStorage.getItem(k);if(r){const s=JSON.parse(r);if(s.length>0){sessionId.value=id;messages.value=s.map(m=>({...m,toolDrawerOpen:false}));streamingContent.value='';streamingReasoning.value='';resultTable.value={visible:false,columns:[],rows:[]};await nextTick();scrollToBottom();return}}}catch{};try{const re=await axios.get(`${API_BASE}/session/${id}/history`,{headers:authHeaders(),timeout:5000});const ms=(re.data&&re.data.messages)||[];if(ms.length>0){sessionId.value=id;messages.value=ms.map(m=>({id:m.id||Date.now(),role:m.role,content:m.content,toolCalls:m.tool_calls||[],toolDrawerOpen:false}));streamingContent.value='';await nextTick();scrollToBottom();return}}catch{};sessionHistory.value=sessionHistory.value.filter(s=>s.id!==id);saveHistoryToStorage();newSession()}
function onCtx(e,s){e.preventDefault();ElMessageBox.confirm('删除会话？','确认',{type:'warning'}).then(()=>{ctxDeleteById(s.id)}).catch(()=>{})}
function ctxDeleteById(id){sessionHistory.value=sessionHistory.value.filter(s=>s.id!==id);saveHistoryToStorage();localStorage.removeItem(STORAGE_KEYS.snapshot(id));if(sessionId.value===id)newSession();ElMessage.success('已删除')}
function favContent(){const favs=JSON.parse(localStorage.getItem(STORAGE_KEYS.favorites)||'[]');if(!favs.find(f=>f.id===sessionId.value)){const first=messages.value.find(m=>m.role==='user');favs.unshift({id:sessionId.value,preview:first?(first.content||'').slice(0,40):'无预览',time:Date.now()});if(favs.length>50)favs.length=50;localStorage.setItem(STORAGE_KEYS.favorites,JSON.stringify(favs));ElMessage.success('已收藏')}else{ElMessage.info('已在收藏夹中')}}
async function sendMessage(){const text=userInput.value.trim();if(!text||isLoading.value)return;userInput.value='';const curCalls=[];toolProgress.value=0;lastQuerySql.value=null;resultTable.value.visible=false;messages.value.push({id:Date.now(),role:'user',content:text});streamingContent.value='';streamingReasoning.value='';showReasoning.value=true;isLoading.value=true;await nextTick();scrollToBottom();const tmr=setInterval(()=>{if(toolProgress.value<90)toolProgress.value+=5},500);try{const resp=await fetch(`${API_BASE}/chat/stream`,{method:'POST',headers:{'Content-Type':'application/json',...authHeaders()},body:JSON.stringify({session_id:sessionId.value,message:text,database:dbConfirmed.value?database.value:null,model:selectedModel.value})});const reader=resp.body.getReader();const dec=new TextDecoder();let buf='';while(true){const{done,value}=await reader.read();if(done)break;buf+=dec.decode(value,{stream:true});const lines=buf.split('\n');buf=lines.pop()||'';for(const line of lines){if(!line.startsWith('data: ')||line.startsWith('data: [DONE]'))continue;try{const d=JSON.parse(line.slice(6));if(d.type==='reasoning'){streamingReasoning.value+=d.text}else if(d.type==='content'){streamingContent.value+=d.text;toolProgress.value=30}else if(d.type==='tool_start'){curCalls.push({name:d.tool,args:d.args,status:'running'});toolProgress.value=60}else if(d.type==='tool_result'){const tc=curCalls.find(c=>c.status==='running');if(tc)tc.status=d.success?'success':'error';toolProgress.value=80;if(tc&&tc.name==='execute_readonly_sql'&&d.success)lastQuerySql.value=(tc.args&&tc.args.sql)||null}}catch{}}await nextTick();scrollToBottom()}}catch(e){streamingContent.value+=' [连接失败]'};clearInterval(tmr);toolProgress.value=100;setTimeout(()=>{if(toolProgress.value===100)toolProgress.value=0},600);if(streamingContent.value){messages.value.push({id:Date.now(),role:'assistant',content:streamingContent.value,reasoning:streamingReasoning.value||undefined,cotOpen:false,toolCalls:curCalls.length?[...curCalls]:[],toolDrawerOpen:true});streamingContent.value='';streamingReasoning.value=''};isLoading.value=false;saveLocalSnapshot();await nextTick();scrollToBottom()}
function quickAction(text){userInput.value=text;sendMessage()}
function handleKeydown(e){if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage()}}
function scrollToBottom(){if(chatHistory.value)chatHistory.value.scrollTop=chatHistory.value.scrollHeight}
function copyText(t){navigator.clipboard.writeText(t).then(()=>ElMessage.success('已复制')).catch(()=>{})}
function renderContent(text){if(!text)return'';let h=text;h=h.replace(/```sql\n([\s\S]*?)```/g,(_,c)=>`<pre class="code-block"><code>${hljs.highlight(c.trim(),{language:'sql'}).value}</code></pre>`);h=h.replace(/```(\w+)?\n([\s\S]*?)```/g,(_,__,c)=>`<pre class="code-block"><code>${c.trim()}</code></pre>`);return h.replace(/`([^`]+)`/g,'<code class="inline-code">$1</code>').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>')}
function hasQueryResult(msg){return msg.toolCalls&&msg.toolCalls.some(c=>c.name==='execute_readonly_sql'&&c.status==='success')}
async function openResultTable(msg){const tc=msg.toolCalls?msg.toolCalls.find(c=>c.name==='execute_readonly_sql'&&c.status==='success'):null;if(!tc||!tc.args||!tc.args.sql)return;try{const r=await axios.post(`${API_BASE}/execute`,{database:database.value,sql:tc.args.sql,limit:500},{headers:authHeaders()});if(r.data&&r.data.columns)resultTable.value={visible:true,columns:r.data.columns,rows:r.data.data||[]};else ElMessage.info('无查询结果')}catch{ElMessage.error('获取失败')}}
function copyResultTable(){if(!resultTable.value.rows.length)return;const cols=resultTable.value.columns;let tsv=cols.join('\t')+'\n';resultTable.value.rows.forEach(r=>{tsv+=cols.map(c=>r[c]!==null&&r[c]!==undefined?r[c]:'NULL').join('\t')+'\n'});navigator.clipboard.writeText(tsv).then(()=>ElMessage.success('已复制')).catch(()=>{})}
function exportResultCSV(){if(!resultTable.value.rows.length)return;const cols=resultTable.value.columns;let csv='\uFEFF'+cols.join(',')+'\n';resultTable.value.rows.forEach(r=>{csv+=cols.map(c=>{let v=r[c];if(v===null||v===undefined)return'NULL';v=String(v);if(v.includes(',')||v.includes('"'))v='"'+v.replace(/"/g,'""')+'"';return v}).join(',')+'\n'});const blob=new Blob([csv],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='查询结果.csv';a.click();ElMessage.success('已导出')}
async function exportCSV(){if(!lastQuerySql.value)return;try{const r=await axios.post(`${API_BASE}/execute`,{database:database.value,sql:lastQuerySql.value,limit:1000},{headers:authHeaders()});const rows=r.data?r.data.data:null;if(!rows||!rows.length)return ElMessage.warning('无数据');const cols=r.data.columns||Object.keys(rows[0]);let csv='\uFEFF'+cols.join(',')+'\n';rows.forEach(row=>{csv+=cols.map(c=>{let v=row[c];if(v===null||v===undefined)return'';v=String(v);if(v.includes(',')||v.includes('"')||v.includes('\n'))v='"'+v.replace(/"/g,'""')+'"';return v}).join(',')+'\n'});const blob=new Blob([csv],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='查询结果.csv';a.click();ElMessage.success('已导出')}catch(e){ElMessage.error('导出失败')}}
async function executeEditorSql(){if(!editorSql.value.trim())return;executingSql.value=true;try{const r=await axios.post(`${API_BASE}/execute`,{database:database.value,sql:editorSql.value,limit:200},{headers:authHeaders()});if(r.data&&r.data.columns){resultTable.value={visible:true,columns:r.data.columns,rows:r.data.data||[]};lastQuerySql.value=editorSql.value}else{ElMessage.error((r.data&&r.data.error)||'执行失败')}}catch(e){ElMessage.error('执行失败')}finally{executingSql.value=false}}
async function doExplainSql(){if(!editorSql.value.trim())return;executingSql.value=true;try{const r=await axios.post(`${API_BASE}/explain`,{database:database.value,sql:editorSql.value},{headers:authHeaders()});showExplainedResult(r.data)}catch(e){ElMessage.error('EXPLAIN失败')}finally{executingSql.value=false}}
function formatEditorSql(){try{editorSql.value=editorSql.value.replace(/\s+/g,' ').trim().replace(/\b(SELECT|FROM|WHERE|JOIN|LEFT JOIN|RIGHT JOIN|INNER JOIN|ON|AND|OR|ORDER BY|GROUP BY|HAVING|LIMIT|UNION|INSERT|UPDATE|DELETE|SET|VALUES)\b/gi,'\n$1').replace(/\n\s*\n/g,'\n').trim()}catch{}}
function showExplainedResult(data){messages.value.push({id:Date.now(),role:'assistant',content:'```sql\n'+safeStr(data.explain_traditional||data)+'\n```\n\n**EXPLAIN 分析结果**',toolCalls:[],toolDrawerOpen:false});saveLocalSnapshot();nextTick(()=>scrollToBottom())}
function toggleSqlEditor(){sqlEditorOpen.value=!sqlEditorOpen.value}
function runInspectChat(){userInput.value='帮我巡检表结构';sendMessage()}
function openSqlForDiagnosis(){if(!lastQuerySql.value){ElMessage.warning('请先执行一次查询（可以通过对话让AI帮你查询，或使用SQL编辑器执行SQL），然后使用诊断功能');return}editorSql.value=lastQuerySql.value;sqlEditorOpen.value=true;navTab.value='chat'}
async function runGenerate(exec){if(!genTable.value.trim()){ElMessage.warning('请先填写表名');return};genLoading.value=true;genResult.value=null;const db=genDb.value||database.value;try{const r=(await axios.post(`${API_BASE}/generate-data`,{database:db,table:genTable.value.trim(),scenario:genScenario.value||'通用数据',row_count:genCount.value},{headers:authHeaders()})).data;if(!r.success){ElMessage.error(r.error||'生成失败');genLoading.value=false;return};genResult.value=r;genHasSql.value=r.insert_statements&&r.insert_statements.length>0;ElMessage.success(`已生成 ${r.row_count||0} 条`);if(exec&&r.insert_statements&&r.insert_statements.length){if(!auth.isAdmin){ElMessage.warning('需要管理员权限');genLoading.value=false;return};const ex=(await axios.post(`${API_BASE}/execute-test-data`,{database:db,insert_statements:r.insert_statements},{headers:authHeaders()})).data;genResult.value.inserted=ex.success?ex.inserted:0;if(!ex.success){genResult.value.error=ex.error||'插入失败';ElMessage.error(genResult.value.error)}}}catch(e){genResult.value={error:e.message}};genLoading.value=false}
const bgCanvas = ref(null); let anim = null, effTimer = null; let effIdx = 0, effTT = 0, drops = [], petals = [], motes = [], sunAngle = 0
function applyStoredTheme(){const t=localStorage.getItem('db_agent_theme');const html=document.querySelector('html');if(!html)return;if(t==='light')html.classList.add('light-theme');else html.classList.remove('light-theme')}
onMounted(()=>{applyStoredTheme();loadSessionHistoryFromStorage();checkHealth();loadDatabases();const pr=localStorage.getItem(STORAGE_KEYS.pendingRestore);if(pr){localStorage.removeItem(STORAGE_KEYS.pendingRestore);loadSessionHistoryFromStorage();restoreSession(pr);return};if(sessionHistory.value.length>0)restoreSession(sessionHistory.value[0].id);else newSession();setInterval(checkHealth,120000);initBg()})
onUnmounted(()=>{if(anim)cancelAnimationFrame(anim);if(effTimer)clearTimeout(effTimer)})
async function checkHealth(){try{backendOnline.value=(await axios.get(`${API_BASE}/health`,{timeout:3000})).data.status==='ok'}catch{backendOnline.value=false}}
function initBg(){const c=bgCanvas.value;if(!c)return;const ctx=c.getContext('2d');let w=0,h=0;const stars=[],meteors=[]
function rs(){w=c.width=c.offsetWidth;h=c.height=c.offsetHeight}rs();window.addEventListener('resize',rs)
for(let i=0;i<180;i++)stars.push({x:Math.random()*1920,y:Math.random()*1080,r:Math.random()*1.6+0.2,s:Math.random()*0.015+0.003,p:Math.random()*Math.PI*2,b:Math.random()*0.35+0.2})
function sm(){meteors.push({x:Math.random()*w*0.8+w*0.1,y:Math.random()*h*0.3,l:Math.random()*80+40,v:Math.random()*5+3,life:1,d:Math.random()*0.01+0.004})}
for(let i=0;i<120;i++)drops.push({x:Math.random()*w,y:Math.random()*h,l:Math.random()*22+10,spd:Math.random()*6+4,op:Math.random()*0.5+0.3})
for(let i=0;i<40;i++)petals.push({x:Math.random()*w,y:Math.random()*h,z:Math.random()*12+8,vx:Math.random()*0.55+0.25,vy:Math.random()*0.25+0.08,wb:Math.random()*Math.PI*2,ws:Math.random()*0.02+0.01,rt:Math.random()*Math.PI*2,rs:Math.random()*0.03-0.015,op:Math.random()*0.5+0.35,h:Math.random()*40+340})
for(let i=0;i<70;i++)motes.push({x:Math.random()*w*0.3,y:Math.random()*h*0.3,r:Math.random()*4+1.2,op:Math.random()*0.55+0.3,vx:Math.random()*0.12-0.06,vy:-Math.random()*0.2-0.04})
function drawPetal(px,py,z,rt,op,h){ctx.save();ctx.translate(px,py);ctx.rotate(rt);ctx.beginPath();ctx.moveTo(0,-z);ctx.bezierCurveTo(z*0.55,-z*0.7,z*0.55,z*0.35,0,z*0.85);ctx.bezierCurveTo(-z*0.55,z*0.35,-z*0.55,-z*0.7,0,-z);ctx.fillStyle=`hsla(${h},75%,72%,${op})`;ctx.fill();ctx.restore()}
function rotateEffect(){const html=document.querySelector('html');if(!html||!html.classList.contains('light-theme')){effTimer=setTimeout(rotateEffect,5000);return};effIdx=(effIdx+1)%3;effTT=0;effTimer=setTimeout(rotateEffect,15000+Math.random()*15000)}
function draw(){ctx.clearRect(0,0,w,h);const lt=document.querySelector('html')?.classList.contains('light-theme');if(!lt){const n=Date.now()*0.001;for(const s of stars){const a=s.b+Math.sin(n*s.s*60+s.p)*0.25;ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fillStyle=`rgba(255,255,255,${Math.max(0.06,a)})`;ctx.fill()}for(let i=meteors.length-1;i>=0;i--){const m=meteors[i];m.x-=m.v;m.y+=m.v*0.5;m.life-=m.d;if(m.life<=0){meteors.splice(i,1);continue};const g=ctx.createLinearGradient(m.x,m.y,m.x+m.l,m.y-m.l*0.5);g.addColorStop(0,`rgba(255,255,255,${m.life*0.7})`);g.addColorStop(1,'rgba(255,255,255,0)');ctx.beginPath();ctx.moveTo(m.x,m.y);ctx.lineTo(m.x+m.l,m.y-m.l*0.5);ctx.strokeStyle=g;ctx.lineWidth=1.3;ctx.stroke()}if(Math.random()<0.004)sm()}else{if(effTimer===null)rotateEffect();effTT+=0.014;const f=Math.min(effTT,1);if(drops.length<80)for(let i=0;i<3;i++)drops.push({x:Math.random()*w,y:-25,l:Math.random()*22+12,spd:Math.random()*6+4,op:Math.random()*0.5+0.3});if(petals.length<30)for(let i=0;i<3;i++)petals.push({x:Math.random()*w,y:-25,z:Math.random()*12+8,vx:Math.random()*0.55+0.25,vy:Math.random()*0.25+0.08,wb:Math.random()*Math.PI*2,ws:Math.random()*0.02+0.01,rt:Math.random()*Math.PI*2,rs:Math.random()*0.03-0.015,op:Math.random()*0.5+0.35,h:Math.random()*40+340});if(motes.length<40)for(let i=0;i<3;i++)motes.push({x:Math.random()*w*0.3,y:Math.random()*h*0.3,r:Math.random()*4+1.2,op:Math.random()*0.55+0.3,vx:Math.random()*0.12-0.06,vy:-Math.random()*0.2-0.04});if(effIdx===0){for(let i=drops.length-1;i>=0;i--){const d=drops[i];d.y+=d.spd;if(d.y>h+35){drops.splice(i,1);continue};ctx.beginPath();ctx.moveTo(d.x,d.y);ctx.lineTo(d.x-d.spd*0.3,d.y+d.l);ctx.strokeStyle=`rgba(140,180,235,${d.op*f})`;ctx.lineWidth=1.2;ctx.stroke()}}else if(effIdx===1){for(let i=petals.length-1;i>=0;i--){const p=petals[i];p.x+=p.vx+Math.sin(Date.now()*0.0015+p.wb)*0.2;p.y+=p.vy;p.rt+=p.rs;p.wb+=p.ws;if(p.y>h+45){petals.splice(i,1);continue};if(p.x<-50)p.x=w+40;if(p.x>w+50)p.x=-40;drawPetal(p.x,p.y,p.z,p.rt,p.op*f,p.h)}}else{sunAngle+=0.0004;for(let i=0;i<8;i++){const a=sunAngle+i*0.785+Math.sin(Date.now()*0.0004+i)*0.06;const dx=Math.cos(a),dy=Math.sin(a);const farX=dx*w*0.95,farY=dy*h*0.85;const topW=8*f,botW=200*f;const g=ctx.createLinearGradient(0,0,farX,farY);g.addColorStop(0,'rgba(255,248,195,0.9)');g.addColorStop(0.15,'rgba(255,235,160,0.65)');g.addColorStop(0.5,'rgba(255,215,110,0.18)');g.addColorStop(1,'rgba(255,180,60,0)');ctx.beginPath();ctx.moveTo(dx*topW,dy*topW);ctx.lineTo(farX-dy*botW,farY+dx*botW);ctx.lineTo(farX+dy*botW,farY-dx*botW);ctx.lineTo(-dx*topW,-dy*topW);ctx.fillStyle=g;ctx.fill()}for(let i=motes.length-1;i>=0;i--){const m=motes[i];m.x+=m.vx;m.y+=m.vy;m.op-=0.0005;if(m.y<-40||m.op<=0){motes.splice(i,1);continue};const glow=ctx.createRadialGradient(m.x,m.y,0,m.x,m.y,m.r*4.5);glow.addColorStop(0,'rgba(255,248,190,0.85)');glow.addColorStop(0.2,'rgba(255,230,140,0.55)');glow.addColorStop(0.55,'rgba(255,205,90,0.15)');glow.addColorStop(1,'rgba(255,170,50,0)');ctx.beginPath();ctx.arc(m.x,m.y,m.r,0,Math.PI*2);ctx.fillStyle=glow;ctx.fill()}}}anim=requestAnimationFrame(draw)}for(let i=0;i<3;i++)sm();draw()}
</script>
